import{_ as t,o as l,c as a,b6 as i}from"./chunks/framework.BUXTSoD9.js";const u=JSON.parse('{"title":"參考 UI 設計規範設計頁面和按鈕","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/frontend/multi-product-ui/index.md","filePath":"zh-tw/stage-2/frontend/multi-product-ui/index.md"}'),n={name:"zh-tw/stage-2/frontend/multi-product-ui/index.md"};function s(r,e,o,p,d,h){return l(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="參考-ui-設計規範設計頁面和按鈕" tabindex="-1">參考 UI 設計規範設計頁面和按鈕 <a class="header-anchor" href="#參考-ui-設計規範設計頁面和按鈕" aria-label="Permalink to “參考 UI 設計規範設計頁面和按鈕”">​</a></h1><p>很多人說&quot;我想讓頁面更像 Apple 一點&quot;&quot;按鈕想做得更高級一點&quot;，但真正開始做時，往往會卡在一個問題上：</p><p><strong>到底該參考什麼？</strong></p><p>盯著截圖模仿，學到的只是&quot;像不像&quot;。但打開 Apple、Google、Microsoft、Atlassian 的設計規範，你會發現它們真正厲害的地方不是視覺風格，而是<strong>把設計問題講清楚</strong>：頁面先突出什麼、按鈕如何分級、操作怎麼強調——這些判斷標準才是核心。</p><blockquote><p>參考設計規範，不是為了做得&quot;像誰&quot;，而是學會別人怎麼做判斷。</p></blockquote><div class="info custom-block"><p class="custom-block-title">為什麼現在還要學這些</p><p>設計規則早已被訓練進模型、被設計工具默認吸收，甚至貼幾張截圖 AI 就能學會。但我們仍然有必要知道這些規則從哪來、為什麼這樣定。</p></div><h2 id="先看幾段原文-感受差距" tabindex="-1">先看幾段原文，感受差距 <a class="header-anchor" href="#先看幾段原文-感受差距" aria-label="Permalink to “先看幾段原文，感受差距”">​</a></h2><p>如果你以前覺得“設計規範不就是講講風格嗎”，先看幾條官方原文。</p><p>平時我們在團隊裡經常會這樣說：</p><ul><li>做個下拉框</li><li>這裡放個菜單</li><li>菜單欄加幾個功能</li><li>這裡放兩個按鈕，一個確認一個取消</li></ul><p>聽起來沒問題，但在大廠規範裡，這些詞都不是模糊概念，而是被拆得非常細。</p><table tabindex="0"><thead><tr><th style="text-align:left;">平時隨口說的話</th><th style="text-align:left;">官方原文</th><th style="text-align:left;">簡單說</th></tr></thead><tbody><tr><td style="text-align:left;">“做個菜單”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">“A menu reveals its options...”</a></td><td style="text-align:left;"><code>Menu</code> 是拿來做操作的</td></tr><tr><td style="text-align:left;">“菜單欄裡放功能”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">“menu bar menus contain all the commands...”</a></td><td style="text-align:left;">這是應用頂部的命令菜單</td></tr><tr><td style="text-align:left;">“做個下拉框”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">“A pop-up list lets the user choose one option among several.”</a></td><td style="text-align:left;"><code>pop-up</code> 是從列表裡選一個</td></tr><tr><td style="text-align:left;">“也做個下拉框”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">“A pull-down list is generally used for selecting commands in a specific context.”</a></td><td style="text-align:left;"><code>pull-down</code> 是點開做當前操作</td></tr><tr><td style="text-align:left;">“菜單也能拿來篩選吧”</td><td style="text-align:left;">Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">“If you need to collect information from people, try a select, dropdown, or combobox instead.”</a></td><td style="text-align:left;"><code>Menu</code> 不是拿來選值的</td></tr><tr><td style="text-align:left;">“菜單也能當導航吧”</td><td style="text-align:left;">Material: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">“Menus should not be used as a primary method for navigation within an app.”</a></td><td style="text-align:left;"><code>Menu</code> 不是主導航</td></tr><tr><td style="text-align:left;">“按鈕隨便寫個 OK / Cancel”</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">“Always use ‘Cancel’ to title a button that cancels the alert’s action.”</a></td><td style="text-align:left;">按鈕文字不能隨便寫</td></tr></tbody></table><blockquote><p>表格裡的引文都可以直接點擊，跳到對應的官方頁面。</p></blockquote><p>這就是第一次真正看設計規範時最容易被震到的地方：</p><blockquote><p>我們平時以為自己在討論 UI，實際上很多時候只是在用一堆含糊詞交流。</p></blockquote><p>Apple 不會只說“做個菜單”；它會繼續區分：</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent 不會只說“下拉框”；它會繼續區分：</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>這就是設計規範的必要性。</p><p>它不是為了讓頁面顯得更專業，而是為了讓團隊在討論 UI 時，不再每個人腦子裡都是不同的東西。</p><h2 id="你將學到" tabindex="-1">你將學到 <a class="header-anchor" href="#你將學到" aria-label="Permalink to “你將學到”">​</a></h2><ol><li>為什麼設計頁面和按鈕時要先看設計規範</li><li>Apple、Material、Fluent、Atlassian 這些規範裡，哪些內容最值得參考</li><li>如何把“頁面層級”和“按鈕層級”設計清楚</li><li>如何讓 AI 參考別人的規範來生成頁面和按鈕</li></ol><h2 id="_1-設計規範為什麼能幫你把頁面做清楚" tabindex="-1">1. 設計規範為什麼能幫你把頁面做清楚 <a class="header-anchor" href="#_1-設計規範為什麼能幫你把頁面做清楚" aria-label="Permalink to “1. 設計規範為什麼能幫你把頁面做清楚”">​</a></h2><p>看完上面這些原文，你會發現一個關鍵點：</p><p><strong>設計規範不是錦上添花，而是在先把詞說準。</strong></p><p>很多頁面不好看，不是因為配色不夠高級，而是因為資訊層級混亂。</p><p>很多按鈕不好用，也不是因為圓角不對，而是因為：</p><ul><li>主按鈕太多，用戶不知道該點哪個</li><li>危險按鈕和普通按鈕看起來差不多</li><li>頁面裡所有按鈕都在搶注意力</li><li>不同頁面裡的按鈕樣式和語義不一致</li></ul><p>成熟的設計規範，恰好就是在解決這些問題。它們通常會定義：</p><table tabindex="0"><thead><tr><th style="text-align:left;">規範內容</th><th style="text-align:left;">它解決什麼問題</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>頁面層級</strong></td><td style="text-align:left;">先看哪裡、後看哪裡，資訊怎麼組織</td></tr><tr><td style="text-align:left;"><strong>視覺基礎</strong></td><td style="text-align:left;">顏色、間距、字體、圓角、陰影怎樣統一</td></tr><tr><td style="text-align:left;"><strong>按鈕層級</strong></td><td style="text-align:left;">主按鈕、次按鈕、文字按鈕、危險按鈕如何區分</td></tr><tr><td style="text-align:left;"><strong>狀態規則</strong></td><td style="text-align:left;">hover、focus、disabled、loading 怎麼表現</td></tr><tr><td style="text-align:left;"><strong>交互語義</strong></td><td style="text-align:left;">哪個按鈕是“確認”，哪個是“取消”，哪個是“更多操作”</td></tr></tbody></table><p>所以，設計規範真正提供的不是一套“皮膚”，而是一套<strong>判斷標準</strong>。</p><h2 id="_2-參考大廠規範時-重點看什麼" tabindex="-1">2. 參考大廠規範時，重點看什麼 <a class="header-anchor" href="#_2-參考大廠規範時-重點看什麼" aria-label="Permalink to “2. 參考大廠規範時，重點看什麼”">​</a></h2><h3 id="_2-1-參考-apple-學習-定義得足夠細-這件事" tabindex="-1">2.1 參考 Apple：學習“定義得足夠細”這件事 <a class="header-anchor" href="#_2-1-參考-apple-學習-定義得足夠細-這件事" aria-label="Permalink to “2.1 參考 Apple：學習“定義得足夠細”這件事”">​</a></h3><p>Apple 最值得學的，不只是視覺上的剋制感，而是它會把概念定義得非常細。</p><p>同樣是很多團隊口中的“菜單”或“下拉框”，Apple 會繼續往下拆：</p><ul><li><code>menu</code>：一組命令、選項或狀態</li><li><code>menu bar menu</code>：應用級命令集合</li><li><code>pop-up button</code>：選擇一個值</li><li><code>pull-down button</code>：在當前上下文裡觸發命令</li><li><code>context menu</code>：與當前對象或任務相關的常用動作</li></ul><p>這套區分非常重要，因為它會直接影響：</p><ul><li>這個組件是拿來選值，還是拿來做動作</li><li>它屬於頁面局部，還是屬於應用級</li><li>它應該長期顯示當前選中值，還是隻臨時展開命令</li></ul><p>當你開始按這種粒度思考時，你設計出來的頁面就會一下子清楚很多。</p><h3 id="_2-2-參考-apple-學習頁面層級和剋制感" tabindex="-1">2.2 參考 Apple：學習頁面層級和剋制感 <a class="header-anchor" href="#_2-2-參考-apple-學習頁面層級和剋制感" aria-label="Permalink to “2.2 參考 Apple：學習頁面層級和剋制感”">​</a></h3><p>Apple Human Interface Guidelines 特別適合學習兩件事：</p><ul><li>頁面如何建立清晰層級</li><li>控件如何在不喧賓奪主的前提下保持明確</li></ul><p>Apple 強調 <code>Hierarchy</code>、<code>Harmony</code>、<code>Consistency</code>。這意味著頁面設計時要回答：</p><ul><li>當前頁面最重要的資訊是什麼</li><li>用戶的主要任務是什麼</li><li>哪個操作該最顯眼，哪個操作應該退後</li></ul><p>如果你參考 Apple 來設計頁面，可以重點借鑑：</p><ul><li>首屏資訊不要太碎，核心內容先聚焦</li><li>用留白、字號、分組建立秩序，而不是靠堆很多邊框</li><li>按鈕不要全部高強調，只有關鍵動作才應該最突出</li></ul><h3 id="_2-3-參考-material-學習清晰的頁面結構" tabindex="-1">2.3 參考 Material：學習清晰的頁面結構 <a class="header-anchor" href="#_2-3-參考-material-學習清晰的頁面結構" aria-label="Permalink to “2.3 參考 Material：學習清晰的頁面結構”">​</a></h3><p>Material Design 很適合學習“頁面是怎麼組織任務流”的。</p><p>它的很多組件和佈局規範，核心都在幫助你明確：</p><ul><li>頁面是瀏覽型，還是執行任務型</li><li>當前頁面是讓用戶閱讀、選擇，還是提交</li><li>一個頁面裡哪些元素應該穩定重複，哪些元素應該響應上下文變化</li></ul><p>如果你參考 Material 來設計頁面，可以重點借鑑：</p><ul><li>頁面區塊清楚，模塊職責明確</li><li>導航、內容區、操作區分工清晰</li><li>不同按鈕樣式對應不同操作優先級</li></ul><h3 id="_2-4-參考-fluent-學習組件邊界和按鈕層級" tabindex="-1">2.4 參考 Fluent：學習組件邊界和按鈕層級 <a class="header-anchor" href="#_2-4-參考-fluent-學習組件邊界和按鈕層級" aria-label="Permalink to “2.4 參考 Fluent：學習組件邊界和按鈕層級”">​</a></h3><p>Fluent 2 很適合後臺、工具型產品和複雜表單系統。它最值得學的地方，是會直接告訴你“不要混用概念”。</p><p>例如它明確寫到：如果你要“collect information”，就不要繼續用 <code>menu</code>，而應該考慮 <code>select</code>、<code>dropdown</code>、<code>combobox</code>。</p><p>這句話非常重要，因為它把很多人腦中的“都差不多”打碎了。</p><p>Fluent 2 也很重視：</p><ul><li>操作層級</li><li>組件語義邊界</li><li>密集資訊場景下的清晰度</li></ul><p>如果你參考 Fluent 來設計按鈕，可以重點借鑑：</p><ul><li><code>Primary button</code> 用來承接當前最重要的動作</li><li><code>Secondary button</code> 用來承接支持性動作</li><li><code>Subtle</code>、<code>Transparent</code> 這類弱強調按鈕用於不該搶主流程的操作</li><li>頁面裡的按鈕數量越多，越要控制視覺優先級</li></ul><h3 id="_2-5-參考-atlassian-學習系統化地管理頁面和按鈕" tabindex="-1">2.5 參考 Atlassian：學習系統化地管理頁面和按鈕 <a class="header-anchor" href="#_2-5-參考-atlassian-學習系統化地管理頁面和按鈕" aria-label="Permalink to “2.5 參考 Atlassian：學習系統化地管理頁面和按鈕”">​</a></h3><p>Atlassian Design System 特別適合“一個團隊做很多頁面”的情況。它強調：</p><ul><li>foundations 是共享基礎</li><li>tokens 是統一視覺決策的方法</li><li>components 是被反覆複用的交互構件</li></ul><p>如果你參考 Atlassian 來做頁面和按鈕，最有價值的是：</p><ul><li>把按鈕尺寸、顏色、圓角、間距做成統一規則</li><li>把頁面佈局的節奏固定下來</li><li>讓不同頁面雖然內容不同，但結構語言一致</li></ul><h2 id="_3-設計頁面時-應該參考規範裡的哪些點" tabindex="-1">3. 設計頁面時，應該參考規範裡的哪些點 <a class="header-anchor" href="#_3-設計頁面時-應該參考規範裡的哪些點" aria-label="Permalink to “3. 設計頁面時，應該參考規範裡的哪些點”">​</a></h2><p>當你看一個設計系統時，不要先問“這個頁面好不好看”，而要先問下面幾個問題。</p><h3 id="_3-1-頁面第一眼-主次是不是明確" tabindex="-1">3.1 頁面第一眼，主次是不是明確 <a class="header-anchor" href="#_3-1-頁面第一眼-主次是不是明確" aria-label="Permalink to “3.1 頁面第一眼，主次是不是明確”">​</a></h3><p>一個頁面通常至少要有三層：</p><ul><li><strong>主資訊</strong>：當前頁面最重要的內容</li><li><strong>輔助資訊</strong>：幫助理解或補充的內容</li><li><strong>次級操作</strong>：不應該干擾主任務的動作</li></ul><p>如果三層沒有拉開，頁面就會“都重要”，等於“都不重要”。</p><h3 id="_3-2-頁面佈局-是不是服務任務而不是堆模塊" tabindex="-1">3.2 頁面佈局，是不是服務任務而不是堆模塊 <a class="header-anchor" href="#_3-2-頁面佈局-是不是服務任務而不是堆模塊" aria-label="Permalink to “3.2 頁面佈局，是不是服務任務而不是堆模塊”">​</a></h3><p>參考規範時，可以特別注意：</p><ul><li>標題區有沒有明確頁面目標</li><li>主內容區是不是圍繞任務組織</li><li>操作按鈕是不是貼近相關內容</li><li>次要資訊有沒有被弱化</li></ul><h3 id="_3-3-頁面裡的操作-是不是有優先級" tabindex="-1">3.3 頁面裡的操作，是不是有優先級 <a class="header-anchor" href="#_3-3-頁面裡的操作-是不是有優先級" aria-label="Permalink to “3.3 頁面裡的操作，是不是有優先級”">​</a></h3><p>很多頁面一眼看過去有 6 個按鈕，結果每個按鈕都像 CTA，這是典型的層級失控。</p><p>更合理的方式是：</p><ul><li>一個區域通常只有一個主動作</li><li>次級動作可以用描邊、文字按鈕或更弱的樣式</li><li>風險動作不要和主動作長得一樣</li></ul><h2 id="_4-設計按鈕時-應該參考規範裡的哪些點" tabindex="-1">4. 設計按鈕時，應該參考規範裡的哪些點 <a class="header-anchor" href="#_4-設計按鈕時-應該參考規範裡的哪些點" aria-label="Permalink to “4. 設計按鈕時，應該參考規範裡的哪些點”">​</a></h2><p>按鈕是最容易被“隨手設計”的部分，但也是最能暴露系統是否成熟的部分。</p><h3 id="_4-1-按鈕先分-語義-再分-樣式" tabindex="-1">4.1 按鈕先分“語義”，再分“樣式” <a class="header-anchor" href="#_4-1-按鈕先分-語義-再分-樣式" aria-label="Permalink to “4.1 按鈕先分“語義”，再分“樣式””">​</a></h3><p>不要先想“藍色按鈕還是黑色按鈕”，先想這個按鈕是什麼角色。</p><p>常見按鈕角色可以這樣分：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按鈕類型</th><th style="text-align:left;">作用</th><th style="text-align:left;">常見樣式策略</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">當前區域最關鍵動作</td><td style="text-align:left;">實心、高對比、最顯眼</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">支持性動作</td><td style="text-align:left;">描邊或低一級強調</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">弱操作</td><td style="text-align:left;">文字或低視覺佔比</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">刪除、停用、清空等風險操作</td><td style="text-align:left;">警示色或明確風險樣式</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">局部工具操作</td><td style="text-align:left;">簡潔、靠近上下文</td></tr></tbody></table><h3 id="_4-2-一個頁面不要有太多-primary-button" tabindex="-1">4.2 一個頁面不要有太多 Primary Button <a class="header-anchor" href="#_4-2-一個頁面不要有太多-primary-button" aria-label="Permalink to “4.2 一個頁面不要有太多 Primary Button”">​</a></h3><p>這是很多新手最容易踩的坑。</p><p>如果頁面上有 4 個主按鈕，那麼等於沒有主按鈕。主按鈕的意義本來就是“告訴用戶現在最應該做什麼”。</p><p>你可以借鑑很多設計系統的共同做法：</p><ul><li>一個主要區域通常只保留一個主按鈕</li><li>取消、返回、關閉一般不和確認按鈕搶同級</li><li>更多操作放到次級按鈕或菜單中</li></ul><h3 id="_4-3-按鈕要能表達狀態變化" tabindex="-1">4.3 按鈕要能表達狀態變化 <a class="header-anchor" href="#_4-3-按鈕要能表達狀態變化" aria-label="Permalink to “4.3 按鈕要能表達狀態變化”">​</a></h3><p>設計規範通常會對按鈕狀態寫得很清楚：</p><ul><li>默認態</li><li>懸停態</li><li>聚焦態</li><li>禁用態</li><li>加載態</li><li>危險態</li></ul><p>這很重要，因為按鈕不是一張靜態圖，而是用戶操作過程中最常被觸發的控件之一。</p><h3 id="_4-4-按鈕文案-也屬於設計的一部分" tabindex="-1">4.4 按鈕文案，也屬於設計的一部分 <a class="header-anchor" href="#_4-4-按鈕文案-也屬於設計的一部分" aria-label="Permalink to “4.4 按鈕文案，也屬於設計的一部分”">​</a></h3><p>按鈕文案不只是“文案問題”，它直接影響用戶理解。</p><p>例如：</p><ul><li><code>保存</code></li><li><code>保存更改</code></li><li><code>立即發佈</code></li><li><code>刪除項目</code></li><li><code>移到回收站</code></li></ul><p>這些文案傳達的心理預期完全不同。成熟規範通常會要求按鈕標籤清楚表達動作，而不是使用含糊詞。</p><h2 id="_5-一個很實用的頁面與按鈕設計清單" tabindex="-1">5. 一個很實用的頁面與按鈕設計清單 <a class="header-anchor" href="#_5-一個很實用的頁面與按鈕設計清單" aria-label="Permalink to “5. 一個很實用的頁面與按鈕設計清單”">​</a></h2><p>你自己設計頁面時，可以先快速過一遍這張清單：</p><h3 id="頁面清單" tabindex="-1">頁面清單 <a class="header-anchor" href="#頁面清單" aria-label="Permalink to “頁面清單”">​</a></h3><ul><li>頁面標題是否清楚說明當前任務</li><li>首屏最重要的資訊是否一眼可見</li><li>頁面是不是按任務流程組織，而不是按想到什麼放什麼</li><li>同一個區域裡是否只有一個主要動作</li><li>次要內容是否被適當弱化</li></ul><h3 id="按鈕清單" tabindex="-1">按鈕清單 <a class="header-anchor" href="#按鈕清單" aria-label="Permalink to “按鈕清單”">​</a></h3><ul><li>這個按鈕是主動作還是次動作</li><li>它為什麼值得比別的按鈕更顯眼</li><li>頁面裡是不是有太多主按鈕</li><li>危險操作是否被明確標識</li><li>按鈕文案是否足夠具體</li></ul><h2 id="_6-怎樣用-ai-參考別人的規範來設計頁面" tabindex="-1">6. 怎樣用 AI 參考別人的規範來設計頁面 <a class="header-anchor" href="#_6-怎樣用-ai-參考別人的規範來設計頁面" aria-label="Permalink to “6. 怎樣用 AI 參考別人的規範來設計頁面”">​</a></h2><p>這一節最實用。</p><p>很多人讓 AI 設計頁面時，只會說：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">幫我做一個設置頁面，要高級一點，參考蘋果風格</span></span></code></pre></div><p>這類提示詞太模糊了，AI 最後通常只能模仿“白底、圓角、陰影”。</p><p>對新手來說，更實用的方式不是自己總結一大段，而是直接把<strong>規範原文裡的關鍵句</strong>貼給 AI。</p><p>這樣做有兩個好處：</p><ul><li>你不用自己先“翻譯”一遍設計思想</li><li>AI 更容易按官方定義去理解頁面和按鈕</li></ul><h3 id="_6-1-例子一-讓-ai-參考-apple-設計一個設置頁面" tabindex="-1">6.1 例子一：讓 AI 參考 Apple 設計一個設置頁面 <a class="header-anchor" href="#_6-1-例子一-讓-ai-參考-apple-設計一個設置頁面" aria-label="Permalink to “6.1 例子一：讓 AI 參考 Apple 設計一個設置頁面”">​</a></h3><p>先找一句 Apple 原文：</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p></blockquote><p>你可以直接這樣貼給 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">參考 Apple Human Interface Guidelines 裡的這句話：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">幫我設計一個賬號安全設置頁面。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要求頁面層級清楚，重要資訊放前面，分組整齊一點。</span></span></code></pre></div><p>這樣寫的重點是：不用你自己解釋太多，直接把 Apple 的原話貼進去。</p><h3 id="_6-2-例子二-讓-ai-參考-fluent-設計後臺頁面按鈕" tabindex="-1">6.2 例子二：讓 AI 參考 Fluent 設計後臺頁面按鈕 <a class="header-anchor" href="#_6-2-例子二-讓-ai-參考-fluent-設計後臺頁面按鈕" aria-label="Permalink to “6.2 例子二：讓 AI 參考 Fluent 設計後臺頁面按鈕”">​</a></h3><p>先找一句 Fluent 原文：</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>你可以直接這樣貼給 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">參考 Fluent 2 裡的這句話：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">幫我設計一個團隊管理後臺的按鈕。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">添加成員按鈕最明顯，導出、篩選、更多操作弱一點，刪除按鈕單獨突出。</span></span></code></pre></div><p>這一句非常適合新手，因為它直接告訴 AI：一個區域不要放太多主按鈕。</p><h3 id="_6-3-例子三-讓-ai-同時參考頁面規範和按鈕規範" tabindex="-1">6.3 例子三：讓 AI 同時參考頁面規範和按鈕規範 <a class="header-anchor" href="#_6-3-例子三-讓-ai-同時參考頁面規範和按鈕規範" aria-label="Permalink to “6.3 例子三：讓 AI 同時參考頁面規範和按鈕規範”">​</a></h3><p>你也可以一次貼兩句原文，讓 AI 同時參考頁面和按鈕：</p><blockquote><p>Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p><p>Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>然後直接這樣寫：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">參考下面兩句設計規範原文：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple: &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent: &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">幫我設計一個項目詳情頁。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">頁面包含項目介紹、成員、最近活動和設置入口。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">頁面層級清楚一點，主按鈕只保留一個，其他按鈕弱一點。</span></span></code></pre></div><p>這種方式特別適合新手，因為你只要會複製原文，再加兩句自己的需求就夠了。</p><h2 id="_7-怎樣用-ai-參考按鈕規範來直接生成按鈕設計" tabindex="-1">7. 怎樣用 AI 參考按鈕規範來直接生成按鈕設計 <a class="header-anchor" href="#_7-怎樣用-ai-參考按鈕規範來直接生成按鈕設計" aria-label="Permalink to “7. 怎樣用 AI 參考按鈕規範來直接生成按鈕設計”">​</a></h2><p>如果你只想先做按鈕，也可以直接貼按鈕規範原文。</p><p>例如 Atlassian 對按鈕的定義很短：</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">&quot;A button triggers an event or action.&quot;</a></p></blockquote><p>你可以這樣問 AI：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">參考 Atlassian 的這句話：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">幫我設計一套後臺頁面按鈕樣式。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我要有主按鈕、次按鈕、刪除按鈕，順便告訴我分別用在什麼地方。</span></span></code></pre></div><p>這類提示詞尤其適合新手，基本就是“貼原文 + 說需求”。</p><h2 id="_8-小結" tabindex="-1">8. 小結 <a class="header-anchor" href="#_8-小結" aria-label="Permalink to “8. 小結”">​</a></h2><p>參考 UI 設計規範設計頁面和按鈕，最重要的不是“做得像誰”，而是學會下面這幾件事：</p><ol><li>用層級組織頁面，而不是把內容堆上去</li><li>用按鈕分級表達操作優先級，而不是讓所有按鈕都一樣搶眼</li><li>用設計規範裡的定義、邊界和判斷標準指導設計</li><li>讓 AI 參考別人規範時，參考的是“原則和結構”，而不是隻參考皮膚</li></ol><p>當你這樣使用規範時，你參考到的就不只是一個風格，而是一套成熟的設計思考方式。</p><hr><h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><p>以下鏈接都來自官方設計系統或官方文檔：</p><ul><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design: <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System: <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System: <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
